def compiler(N):
 H=np.block([[np.zeros((40,40)),N],[N.T,np.zeros((40,40))]])
 alpha=-3/20+4*np.sqrt(6)/15;beta=1/40-np.sqrt(6)/60
 P=alpha*H+beta*np.linalg.matrix_power(H,3);w,V=np.linalg.eigh(H);S=(V*np.where(abs(w)>1e-9,np.sign(w),0))@V.T
 err=float(np.linalg.norm(P-S,2));assert err<1e-12
