def ds_w33(t):
 z=1+24*np.exp(-10*t)+15*np.exp(-16*t);return 2*t*(240*np.exp(-10*t)+240*np.exp(-16*t))/z
def ds_line(t):
 vals=[0,4-np.sqrt(6),4,4+np.sqrt(6),8];mul=[1,24,30,24,81]
